const root=document.documentElement;
const theme=document.querySelector('#theme');
function themeLabel(){theme.setAttribute('aria-label',`Activar tema ${root.dataset.theme==='dark'?'claro':'oscuro'}`);document.querySelector('meta[name="theme-color"]').content=root.dataset.theme==='dark'?'#101212':'#f8f8f5'}
themeLabel();theme.addEventListener('click',()=>{root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('kodex-theme',root.dataset.theme)}catch{}themeLabel()});
const menu=document.querySelector('#menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Cerrar menú':'Abrir menú');nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menú')}));
const slides=[{kicker:'KODEX GAMING / PLAY BEYOND',title:'Tu siguiente nivel<br>empieza aquí.',description:'El poder de jugar, crear y superar tus límites.<br>Encuentra tu universo en KODEX Gaming.',label:'Explorar Gaming',href:'https://gaming.kodex.com.do',image:'gaming.webp',color:'#adf299'}, {kicker:'KODEX SOLUTIONS / WORK FORWARD',title:'Ideas que crecen.<br>Tecnología que impulsa.',description:'Un nuevo universo para tu empresa.<br>Descubre equipos, impresión y nuevas posibilidades.',label:'Explorar Solutions',href:'https://solutions.kodex.com.do',image:'office.webp',color:'#abd8ff'},{kicker:'BIENVENIDO AL UNIVERSO KODEX',title:'Dos mundos.<br>Infinitas posibilidades.',description:'Juega. Crea. Trabaja. Avanza.<br>Conecta con la tecnología que te mueve.',label:'Elige tu mundo',href:'#universos',image:'monitor.webp',color:'#fff'}];
let current=0,timer,paused=matchMedia('(prefers-reduced-motion: reduce)').matches;
const tabs=[...document.querySelectorAll('.slide-tab')],pause=document.querySelector('#pause');
function show(i){current=(i+slides.length)%slides.length;const s=slides[current];document.querySelector('#hero-kicker').textContent=s.kicker;document.querySelector('#hero-kicker').style.color=s.color;document.querySelector('#hero-title').innerHTML=s.title;document.querySelector('#hero-description').innerHTML=s.description;const a=document.querySelector('#hero-link');a.href=s.href;a.innerHTML=s.label+' <span>↗</span>';document.querySelector('.hero-image').style.backgroundImage=`url('assets/${s.image}')`;tabs.forEach((t,j)=>{t.classList.toggle('active',j===current);t.setAttribute('aria-pressed',String(j===current))})}
function start(){clearInterval(timer);if(!paused&&!document.hidden)timer=setInterval(()=>show(current+1),7000)}
function setPause(){pause.textContent=paused?'▶':'Ⅱ';pause.setAttribute('aria-label',paused?'Reanudar el carrusel':'Pausar carrusel');start()}
pause.addEventListener('click',()=>{paused=!paused;setPause()});tabs.forEach((t,i)=>t.addEventListener('click',()=>{show(i);start()}));document.querySelector('#prev').addEventListener('click',()=>{show(current-1);start()});document.querySelector('#next').addEventListener('click',()=>{show(current+1);start()});document.addEventListener('visibilitychange',start);document.querySelector('.hero').addEventListener('focusin',()=>clearInterval(timer));document.querySelector('.hero').addEventListener('focusout',start);setPause();
const products=[{brand:'gaming',title:'PCs para ir más allá',category:'POTENCIA / GAMING',description:'El centro de tu próximo setup.',image:'gaming.webp',alt:'Interior de un equipo de escritorio con iluminación'}, {brand:'gaming',title:'Cada movimiento cuenta',category:'PERIFÉRICOS / GAMING',description:'Teclados y accesorios para tu espacio.',image:'keyboard.webp',alt:'Teclado mecánico sobre escritorio'}, {brand:'solutions',title:'Tu oficina, conectada',category:'EQUIPOS / SOLUTIONS',description:'Computadoras para tus proyectos.',image:'laptop.webp',alt:'Computadora portátil en un escritorio'}, {brand:'solutions',title:'Haz una buena impresión',category:'IMPRESIÓN / SOLUTIONS',description:'Impresoras para el día a día de tu empresa.',image:'printer.webp',alt:'Impresora multifunción de oficina'}];
document.querySelector('#products').innerHTML=products.map(p=>`<a class="product" data-brand="${p.brand}" href="https://${p.brand}.kodex.com.do"><div class="product-image"><img src="assets/${p.image}" alt="${p.alt}" loading="lazy" width="700" height="500"><span class="product-badge">KODEX ${p.brand.toUpperCase()}</span></div><div class="product-body"><small>${p.category}</small><h3>${p.title}</h3><p>${p.description}</p><div class="product-bottom"><span>Explorar ${p.brand==='gaming'?'Gaming':'Solutions'}</span><span>↗</span></div></div></a>`).join('');
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelectorAll('.product').forEach(p=>p.hidden=b.dataset.filter!=='all'&&p.dataset.brand!==b.dataset.filter)}));document.querySelector('#year').textContent=new Date().getFullYear();
